def b91decode(strng):
    b = 0
    n = 0
    out = []
    for c in strng:
        if c not in 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,./:;<=>?@[]^_`{|}~"':
            continue
        v = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,./:;<=>?@[]^_`{|}~"'.index(c)
        if v < 0:
            continue
        b |= v << n
        n += 7 if v & 0x7F == v else 14
        while n > 7:
            out.append(chr(b & 0xFF))
            b >>= 8
            n -= 8
    if n > 0:
        out.append(chr(b & 0xFF))
    return ''.join(out)

class Solution:
    def maxSizeSlices(self, slices: List[int]) -> int:
        def dp_linear(arr):
            n = len(arr)
            k = n // 3
            dp = [[0] * (k + 1) for _ in range(n + 1)]
            for i in range(1, n + 1):
                for j in range(1, k + 1):
                    dp[i][j] = max(dp[i-1][j], (dp[i-2][j-1] if i >= 2 else 0) + arr[i-1])
            return dp[n][k]
        return max(dp_linear(slices[:-1]), dp_linear(slices[1:]))

class Solution:
    def numTimesAllBlue(self, light: List[int]) -> int:
        max_bulb = 0
        count = 0
        for i, bulb in enumerate(light):
            max_bulb = max(max_bulb, bulb)
            if max_bulb == i + 1:
                count += 1
        return count

class Solution:
    def unhappyFriends(self, n: int, preferences: List[List[int]], pairs: List[List[int]]) -> int:
        pair_map = {}
        for x, y in pairs:
            pair_map[x] = y
            pair_map[y] = x
        unhappy = set()
        for x in range(n):
            y = pair_map[x]
            for u in preferences[x]:
                if u == y:
                    break
                v = pair_map[u]
                if preferences[u].index(x) < preferences[u].index(v):
                    unhappy.add(x)
                    break
        return len(unhappy)

class Solution:
    def minSwaps(self, grid: List[List[int]]) -> int:
        n = len(grid)
        zeros = [0] * n
        for i in range(n):
            count = 0
            for j in range(n - 1, -1, -1):
                if grid[i][j] == 0:
                    count += 1
                else:
                    break
            zeros[i] = count
        res = 0
        for i in range(n):
            required = n - i - 1
            j = i
            while j < n and zeros[j] < required:
                j += 1
            if j == n:
                return -1
            while j > i:
                zeros[j], zeros[j - 1] = zeros[j - 1], zeros[j]
                res += 1
                j -= 1
        return res
